import json

def safe_parse(raw):
    clean = raw.strip()
    # Remove trailing (.venv) prompt
    if clean.endswith('(.venv)'):
        clean = clean[:-len('(.venv)')].strip()
    # Handle stderr
    clean = clean.split('\n[stderr]\n', 1)[0].strip()
    # Remove any trailing (.venv) again after stderr split
    if clean.endswith('(.venv)'):
        clean = clean[:-len('(.venv)')].strip()
    return json.loads(clean)

